    "q": "<figure class=\"aa-source\"><img class=\"source-facsimile\" src=\"assets/aa-ws2-ph-q1.png\" alt=\"Workshop 2 original source extract\" loading=\"eager\"></figure>",
    "a": "<figure class=\"aa-source\"><img class=\"source-facsimile\" src=\"assets/aa-ws2-ph-q1-a1.png\" alt=\"Workshop 2 original source extract\" loading=\"eager\"></figure><figure class=\"aa-source\"><img class=\"source-facsimile\" src=\"assets/aa-ws2-ph-q1-a2.png\" alt=\"Workshop 2 original source extract\" loading=\"eager\"></figure>",
